import sanitizeHtml from "sanitize-html";

const MEDIA_SRC = /^\/media\/[a-z]+\/[0-9a-f-]{36}\.[a-z0-9]{2,5}$/;
const SAFE_COLOR = /^(#[0-9a-f]{3,8}|rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*(,\s*(0|1|0?\.\d+))?\s*\))$/i;

const isOwnMedia = (src: string | undefined) => typeof src === "string" && MEDIA_SRC.test(src);

/**
 * Defence-in-depth HTML sanitiser for rich text. The HTML is generated by our own
 * renderer from a validated schema, but it is still passed through a strict
 * allow-list before it is stored or rendered.
 */
const OPTIONS: sanitizeHtml.IOptions = {
  allowedTags: [
    "p", "br", "hr", "h2", "h3", "h4", "strong", "b", "em", "i", "u", "s", "code", "pre", "blockquote",
    "ul", "ol", "li", "a", "img", "video", "mark", "sub", "sup", "span", "div", "iframe", "label", "input",
    "table", "colgroup", "col", "thead", "tbody", "tr", "th", "td",
  ],
  allowedAttributes: {
    a: ["href", "target", "rel", "class", "download", "data-size"],
    img: ["src", "alt", "title", "width", "height", "loading"],
    video: ["src", "poster", "controls", "preload", "playsinline", "class"],
    iframe: ["src", "width", "height", "allowfullscreen", "allow", "loading"],
    div: ["data-youtube-video"],
    ul: ["data-type"],
    li: ["data-type", "data-checked"],
    input: ["type", "checked", "disabled"],
    code: ["class"],
    span: ["style", "class"],
    p: ["style"],
    h2: ["style"],
    h3: ["style"],
    h4: ["style"],
    th: ["colspan", "rowspan"],
    td: ["colspan", "rowspan"],
    col: ["style"],
  },
  allowedClasses: {
    code: [/^language-[a-z0-9-]+$/],
    a: ["rt-file"],
    video: ["rt-video"],
    span: [/^hljs[a-z-]*$/],
  },
  allowedStyles: {
    "*": {
      "text-align": [/^(left|right|center|justify)$/],
      color: [SAFE_COLOR],
      "min-width": [/^\d{1,4}px$/],
    },
  },
  allowedSchemes: ["http", "https", "mailto"],
  allowedSchemesByTag: { img: [], video: [] },
  allowProtocolRelative: false,
  allowedIframeHostnames: ["www.youtube-nocookie.com", "www.youtube.com"],
  allowIframeRelativeUrls: false,
  transformTags: {
    a: (tagName, attribs) => {
      const isFile = attribs.class === "rt-file";
      if (isFile && !isOwnMedia(attribs.href)) return { tagName: "span", attribs: {} };
      return {
        tagName,
        attribs: isFile
          ? { ...attribs, download: "" }
          : { ...attribs, rel: "noopener noreferrer nofollow", target: "_blank" },
      };
    },
    input: (_tagName, attribs) => ({
      tagName: "input",
      attribs: { type: "checkbox", disabled: "disabled", ...(attribs.checked !== undefined ? { checked: "checked" } : {}) },
    }),
    iframe: (tagName, attribs) => ({
      tagName,
      attribs: { ...attribs, loading: "lazy", allow: "encrypted-media; picture-in-picture; fullscreen" },
    }),
  },
  exclusiveFilter: (frame) => {
    if (frame.tag === "img") return !isOwnMedia(frame.attribs.src);
    if (frame.tag === "video") return !isOwnMedia(frame.attribs.src) || (Boolean(frame.attribs.poster) && !isOwnMedia(frame.attribs.poster));
    if (frame.tag === "input") return frame.attribs.type !== "checkbox";
    return false;
  },
};

export function sanitizeRichHtml(html: string): string {
  return sanitizeHtml(html, OPTIONS);
}

/** Strips every tag – used for plain-text excerpts and meta descriptions. */
export function toPlainText(html: string): string {
  const spaced = html.replace(/<\/(p|h[1-6]|li|blockquote|pre|td|th|div)>|<br\s*\/?>/gi, "$& ");
  return sanitizeHtml(spaced, { allowedTags: [], allowedAttributes: {} }).replace(/\s+/g, " ").trim();
}
